-- London — Additional Locations
-- Skips existing: The Ritz Hotel Palm Court, Claridge's Lobby Bar, The Connaught Bar,
--   The Savoy American Bar, Annabel's, The Wolseley, Fortnum & Mason,
--   Burlington Arcade, The Wallace Collection
-- Adds 41 new locations.

INSERT INTO locations (city_id, name, neighborhood, category, description, latitude, longitude, photo_url, vibe_difficulty, what_to_wear, is_approved) VALUES

('11111111-0000-0000-0000-000000000002',
'The Dorchester',
'Mayfair',
'Hotel Lobby',
'The Dorchester has occupied the east side of Hyde Park since 1931 and has not particularly changed its opinion of itself since. The Promenade lobby — all gilded mirrors, fresh flowers the size of small trees, and afternoon light from the park — is one of the great London public rooms. The Bar at The Dorchester is a serious place for a serious drink. Arrive as though the car is waiting.',
51.5076, -0.1527,
NULL,
4,
'{"men": {"brands": ["Huntsman", "Brioni", "Patek Philippe", "George Cleverley"], "outfit": {"top": "A dark suit in navy or charcoal — The Dorchester is a jacket situation at all hours", "bottom": "Matching trousers, pressed to a crease", "shoes": "Black or dark tan cap-toe Oxfords, mirror-polished", "bag": "Nothing or a slim leather attaché", "accessories": "Patek Philippe or Jaeger-LeCoultre, a silk pocket square in cream, no other jewelry"}, "color_palette": "Navy, charcoal, white — the palette of someone who has stayed in Park Lane-facing rooms before", "budget_dupe": "A well-tailored dark suit from SuitSupply worn with properly polished shoes. The Dorchester''s staff will treat you identically regardless of the label inside the jacket."}, "women": {"brands": ["Oscar de la Renta", "Roland Mouret", "Cartier", "Gianvito Rossi"], "outfit": {"top": "A structured day dress in a jewel tone or a tailored suit in ivory or pale grey", "bottom": "(dress) or slim tailored trousers", "shoes": "A proper heel — court shoe or pointed kitten heel in nude or black", "bag": "A structured top-handle in black or tan, small and serious", "accessories": "Cartier Love or Panthère, pearl drop earrings, a single thin bracelet"}, "color_palette": "Deep sapphire, ivory, champagne, blush — The Dorchester''s flowers set the colour standard and they are always extraordinary", "budget_dupe": "A beautifully cut dress from LK Bennett or a secondhand Roland Mouret. The Dorchester rewards silhouette above everything else."}}',
true),

('11111111-0000-0000-0000-000000000002',
'The Lanesborough',
'Hyde Park Corner',
'Hotel Lobby',
'Built as St George''s Hospital in 1828 and converted by Grace Leo-Andrieu into a Regency house hotel in 1991, The Lanesborough operates at a register of luxury that does not feel the need to announce itself. The Library Bar serves some of the finest cocktails in London in a room of mahogany shelves and firelight. The butler service is genuine. The clientele is the international wealthy — the kind who give their location as Hyde Park Corner.',
51.5020, -0.1533,
NULL,
5,
'{"men": {"brands": ["Anderson & Sheppard", "Kiton", "A. Lange & Söhne", "John Lobb"], "outfit": {"top": "A Savile Row suit or a blazer of comparable quality — The Lanesborough is a building that rewards proper dressing", "bottom": "Matching or coordinated trousers in dark grey or navy", "shoes": "John Lobb or Edward Green in black, mirror shine", "bag": "Nothing", "accessories": "A. Lange & Söhne or Patek Philippe, a real silk tie for evening, a pocket square always"}, "color_palette": "Midnight navy, charcoal, cream — the palette of a private house staffed by people who know what you want before you do", "budget_dupe": "A very well-fitted dark suit from anywhere, impeccably pressed and worn with real leather shoes. The Lanesborough Library Bar is intimate and warmly lit — fabric quality matters less than fit and intention."}, "women": {"brands": ["Emilia Wickstead", "Victoria Beckham", "Van Cleef & Arpels", "Manolo Blahnik"], "outfit": {"top": "A silk evening dress or a structured cocktail dress in a deep colour — midnight blue, emerald, or black", "bottom": "(dress) or wide-leg silk trousers for a more contemporary read", "shoes": "A pointed-toe heel in satin or leather", "bag": "A small evening bag in leather or satin — structured, unencumbered", "accessories": "Van Cleef or Cartier, a statement earring in one ear if you wish, delicate chain"}, "color_palette": "Midnight blue, deep emerald, ivory, champagne — Regency grandeur interpreted for the present", "budget_dupe": "A silk dress sourced secondhand from a good consignment shop. The Library Bar is candlelit and generous. A beautiful dress from any decade reads correctly here."}}',
true),

('11111111-0000-0000-0000-000000000002',
'Brown''s Hotel',
'Mayfair',
'Hotel Lobby',
'The oldest hotel in London, opened in 1837 by James Brown, formerly Lord Byron''s manservant. Rudyard Kipling wrote part of The Jungle Book here. Agatha Christie set a murder here. The English Tea Room does the most serious afternoon tea in Mayfair — better than The Ritz by a significant margin, with a third the queue. The Donovan Bar, named after Terence Donovan, is unexpectedly good. Arrive as a regular, even if it''s your first time.',
51.5094, -0.1421,
NULL,
4,
'{"men": {"brands": ["Gieves & Hawkes", "Ralph Lauren Purple Label", "IWC", "Crockett & Jones"], "outfit": {"top": "A blazer in navy or heritage tweed over a cream or pale blue shirt — Brown''s rewards the country-in-town register", "bottom": "Dark flannel or cavalry twill trousers", "shoes": "Crockett & Jones or Church''s in tan or dark brown, well-polished", "bag": "Nothing or a leather-handled document case", "accessories": "IWC Portugieser or an antique pocket watch — Brown''s is the right hotel for a pocket watch"}, "color_palette": "Navy, heritage tweed, tan — 1837 to present, uninterrupted", "budget_dupe": "A good tweed blazer from a charity shop near Marylebone (they exist), pressed dark trousers from M&S, Church''s shoes from their own sale. Brown''s is old enough to recognise good breeding regardless of recent provenance."}, "women": {"brands": ["Mulberry", "Temperley London", "Asprey", "L.K. Bennett"], "outfit": {"top": "A printed silk blouse in a Liberty or botanical print, or a fine cashmere in rose or sage", "bottom": "A tailored A-line skirt in a muted print or slim trousers in warm grey", "shoes": "A low block heel or court shoe in tan or soft burgundy", "bag": "A Mulberry Bayswater — this is literally the correct bag for Brown''s Hotel", "accessories": "Pearl or coral earrings, a thin gold chain, a silk scarf if the weather demands it"}, "color_palette": "Sage, dusty rose, ivory, tan — the English country house come to Albemarle Street", "budget_dupe": "John Lewis does the cashmere and the court shoe at exactly the right price for Brown''s. A Mulberry Bayswater from eBay in tan completes the look with total authenticity."}}',
true),

('11111111-0000-0000-0000-000000000002',
'The Beaumont',
'Mayfair',
'Hotel Lobby',
'Jeremy King''s hotel in Brown Hart Gardens opened in 2014 in a 1926 building and immediately became what The Savoy and Claridge''s are to their respective clienteles but for a younger, more discreet money. The Colony Grill Room is the best hotel restaurant in London for American-style grill food done properly. GOAT — Antony Gormley''s room-sized sculpture — is in the building. The whole place operates quietly and with extraordinary conviction.',
51.5134, -0.1473,
NULL,
4,
'{"men": {"brands": ["Favourbrook", "Timothy Everest", "Rolex", "Gaziano & Girling"], "outfit": {"top": "A beautifully cut blazer in midnight navy or dark green — The Beaumont rewards considered dressing rather than formal dressing", "bottom": "Dark tailored trousers or premium dark jeans for the bar", "shoes": "A quality leather shoe in dark tan or black, nothing casual", "bag": "Nothing or a very slim card holder", "accessories": "Rolex Explorer or a vintage Omega, a pocket square in a muted colour"}, "color_palette": "Midnight navy, dark green, ivory — a 1920s American hotel filtered through the best British taste", "budget_dupe": "A well-cut dark blazer and premium dark jeans from anywhere, properly fitted. The Beaumont''s Colony Grill celebrates the kind of dressing where the intention matters as much as the execution."}, "women": {"brands": ["The Row", "Toteme", "Cartier", "Aquazzura"], "outfit": {"top": "A silk or crepe blouse in ivory or deep navy, or a structured minimal dress", "bottom": "Tailored wide-leg trousers in cream or charcoal", "shoes": "A pointed-toe heel or clean loafer in tan or black", "bag": "A structured leather bag — The Row or anything without visible branding", "accessories": "Cartier Love bracelet, simple gold earrings, a thin chain"}, "color_palette": "Ivory, deep navy, camel — quiet luxury at its most considered", "budget_dupe": "COS or Arket for the wide-leg trouser and blouse combination. One good quality bag. The Beaumont''s lighting is warm and the room forgiving."}}',
true),

('11111111-0000-0000-0000-000000000002',
'The Ned',
'City of London',
'Hotel Lobby',
'A 1924 former Midland Bank headquarters designed by Edwin Lutyens, converted by Nick Jones and the Soho House group into a members'' club and hotel of staggering architectural ambition. The banking hall alone — all original marble columns, gilded ceiling, and now eight restaurants — is one of the most extraordinary rooms in London. Non-members can eat in the restaurants. The lobby is free. It is worth seeing for the architecture regardless of anything else.',
51.5137, -0.0921,
NULL,
3,
'{"men": {"brands": ["Reiss", "Paul Smith", "Uniform Wares", "Grenson"], "outfit": {"top": "A sharp navy or charcoal blazer or a Soho House-adjacent quality shirt — The Ned is members'' club smart rather than Mayfair formal", "bottom": "Dark slim trousers or premium dark jeans", "shoes": "Clean leather Derby or Chelsea boot", "bag": "A slim leather tote or nothing", "accessories": "A considered watch — Uniform Wares or a vintage Seiko reads correctly here"}, "color_palette": "Navy, charcoal, dark tan — the City of London''s palette adapted for people who work in creative industries", "budget_dupe": "Paul Smith does the exact look for The Ned at a fraction of the Savile Row equivalent. A blazer and good jeans. The banking hall will make any outfit look significant."}, "women": {"brands": ["Reformation", "Reiss", "Astley Clarke", "& Other Stories"], "outfit": {"top": "A silk wrap dress or a structured blouse in a jewel tone — the banking hall''s gilded ceiling rewards colour", "bottom": "(dress) or tailored wide-leg trousers in dark navy or emerald", "shoes": "A modest heel or clean pointed-toe flat", "bag": "A quality leather bag without excessive branding", "accessories": "Gold stud earrings, a delicate necklace, minimal and intentional"}, "color_palette": "Emerald, deep navy, ivory — the Lutyens building''s gilt and marble pulls everything toward grandeur", "budget_dupe": "A Reformation wrap dress or a good blouse from & Other Stories. The architecture provides most of the atmosphere — your job is to not undercut it."}}',
true),

('11111111-0000-0000-0000-000000000002',
'Rosewood London',
'Holborn',
'Hotel Lobby',
'Converted from the 1914 Pearl Assurance headquarters on High Holborn, Rosewood London has one of the most spectacular hotel lobbies in the city — a triple-height atrium with an original copper dome and a staircase of extraordinary proportions. The Holborn Dining Room has the best pie in London (this is not debatable). The Scarfes Bar is a serious late-night destination with Scarfe drawings covering every wall.',
51.5177, -0.1176,
NULL,
3,
'{"men": {"brands": ["Oliver Spencer", "Paul Smith", "Nomos", "Tricker''s"], "outfit": {"top": "A quality blazer in a warm earth tone — camel, tobacco, rust — responding to the building''s copper and marble", "bottom": "Dark tailored trousers or slim dark jeans", "shoes": "Leather brogues or Derby in tan or dark brown", "bag": "A leather tote or document case", "accessories": "A Nomos Tangente or vintage watch, a simple signet ring"}, "color_palette": "Tobacco, camel, rust, dark navy — the Edwardian civic building aesthetic interpreted for today", "budget_dupe": "Oliver Spencer sale items are made for this aesthetic. A quality blazer in a warm tone, dark jeans, leather brogues. The Rosewood''s interiors are genuinely magnificent and elevate every outfit."}, "women": {"brands": ["Ulla Johnson", "Saloni", "Monica Vinader", "Russell & Bromley"], "outfit": {"top": "A floral or warm-toned dress — the building''s copper and warm stone reward earthy florals", "bottom": "(dress) or wide-leg trousers in rust or tobacco", "shoes": "Ankle boots in cognac or a low block heel", "bag": "A structured leather bag in a warm tone", "accessories": "Monica Vinader gold hoops, a layered necklace, a ring or two"}, "color_palette": "Rust, copper, warm ivory, dark navy — the building''s own palette is the instruction", "budget_dupe": "A floral dress from Anthropologie or Boden in warm tones. Leather ankle boots from any good high street brand. The Rosewood atrium does the rest."}}',
true),

('11111111-0000-0000-0000-000000000002',
'5 Hertford Street',
'Mayfair',
'Old Money',
'Robin Birley''s members'' club at 5 Hertford Street has been the most exclusive address in Mayfair nightlife since 2012. You cannot get in without membership or the escort of a member. You should walk past it on a Friday evening and observe who is arriving. The green door, the Georgian facade, the discreet brass plate — it is everything a private members'' club should look like from the outside, which is most of what most people will see.',
51.5096, -0.1490,
NULL,
5,
'{"men": {"brands": ["Huntsman", "Holland & Holland", "Patek Philippe", "George Cleverley"], "outfit": {"top": "A proper suit or dinner jacket — this is after-dark Mayfair and the dress code is enforced", "bottom": "Matching trousers, no exceptions", "shoes": "Black Oxfords, polished until they reflect", "bag": "Nothing", "accessories": "Patek Philippe, pocket square, possibly a signet ring — nothing else"}, "color_palette": "Black, midnight navy, white — London late-night at its most formal", "budget_dupe": "You cannot enter without a member. Walk past looking like someone who was once a member and didn''t renew for reasons of their own choosing."}, "women": {"brands": ["Alexander McQueen", "Stella McCartney", "Bulgari", "Christian Louboutin"], "outfit": {"top": "A cocktail dress in black, midnight blue, or deep emerald — the kind you save for occasions that justify it", "bottom": "(dress) or a silk jumpsuit with a structured jacket", "shoes": "A real heel — this is the venue that justifies Christian Louboutin", "bag": "A small evening clutch, preferably in satin or beaded fabric", "accessories": "A statement piece — one significant earring or cuff, not both"}, "color_palette": "Black, deep emerald, midnight — Mayfair after dark requires full commitment to the occasion", "budget_dupe": "The LARP here is to walk past looking like you''re on your way somewhere equally exclusive. A beautiful coat and the right shoes are enough for the pavement."}}',
true),

('11111111-0000-0000-0000-000000000002',
'Dukes Bar',
'St James''s',
'Continental',
'The bar at Dukes Hotel on St James''s Place has been making arguably the best martini in London since the 1970s, when Ian Fleming — a regular — was said to have inspired the shaken-not-stirred instruction. The bar is the size of a drawing room and serves a maximum of two martinis per person. The barmen in white jackets bring the trolley to you. You are drinking history.',
51.5055, -0.1420,
NULL,
4,
'{"men": {"brands": ["Turnbull & Asser", "Hackett", "Jaeger-LeCoultre", "Crockett & Jones"], "outfit": {"top": "A blazer or suit jacket — Dukes is St James''s and the register here is club formality without the ostentation", "bottom": "Dark flannel or charcoal trousers", "shoes": "Black or dark tan Oxford, no suede at evening", "bag": "Nothing", "accessories": "Jaeger-LeCoultre Reverso or any quality dress watch, no other accessories — this bar is about simplicity and restraint"}, "color_palette": "Navy, charcoal, cream — the palette of a man who has ordered a martini the same way for thirty years", "budget_dupe": "A dark suit or blazer from anywhere well-fitted, good leather shoes. Dukes Bar is small, intimate, and not interested in your label. It is interested in your composure."}, "women": {"brands": ["Amanda Wakeley", "LK Bennett", "Cartier", "Manolo Blahnik"], "outfit": {"top": "A silk blouse in champagne or pale ivory, or a tailored shift dress in navy", "bottom": "(dress) or slim tailored trousers in dark navy", "shoes": "A modest heel in black or nude satin", "bag": "A small structured clutch — this is a two-martini bar, nothing larger is appropriate", "accessories": "Cartier or pearl, a thin bracelet, small earrings"}, "color_palette": "Champagne, ivory, midnight navy — the two-martini drawing room demands restraint and elegance", "budget_dupe": "A well-cut dark dress from LK Bennett or Reiss. One real piece of jewelry. Dukes Bar is about the quality of your conversation, not the brand of your clothes."}}',
true),

('11111111-0000-0000-0000-000000000002',
'The American Bar at The Stafford',
'St James''s',
'Continental',
'The Stafford''s American Bar is covered — ceiling, walls, every surface — in objects left by generations of American guests since the Second World War: baseball caps, license plates, photographs, Zippo lighters, signed dollar bills. The result is one of the most warmly eccentric bar rooms in London. Order a classic cocktail. Read the ceiling. Understand that some bars are collections as much as they are rooms.',
51.5053, -0.1418,
NULL,
3,
'{"men": {"brands": ["Ralph Lauren", "Polo", "Seiko", "Sanders"], "outfit": {"top": "A navy blazer or a quality shirt — the American Bar is St James''s in formality but warmer in spirit", "bottom": "Dark chinos or pressed dark jeans", "shoes": "Leather loafers or clean Derby", "bag": "Nothing", "accessories": "A watch with a history — a vintage Seiko or a family heirloom is more appropriate here than a new Patek"}, "color_palette": "Navy, cream, old leather — the palette of a room that has been collecting things since 1946", "budget_dupe": "A navy blazer from anywhere, dark trousers, leather shoes. The Stafford Bar is the warmest room in St James''s and forgiving about everything except visible disrespect."}, "women": {"brands": ["Ralph Lauren", "Hobbs", "Monica Vinader", "Russell & Bromley"], "outfit": {"top": "A classic blouse or a fine knit in a warm tone — navy, burgundy, camel", "bottom": "Slim trousers or a tailored A-line skirt", "shoes": "A low block heel or loafer in tan or burgundy", "bag": "A structured leather bag or a quality clutch", "accessories": "Gold hoops, a chain necklace — classics that don''t try too hard"}, "color_palette": "Navy, burgundy, camel, cream — a bar that has been collecting Americana since before you were born rewards warmth over fashion", "budget_dupe": "Hobbs and John Lewis do this look precisely. A quality blouse and good trousers. The American Bar will make you feel that you''ve been coming here for years regardless."}}',
true),

('11111111-0000-0000-0000-000000000002',
'Mark''s Club',
'Mayfair',
'Old Money',
'Mark Birley''s private dining club at 46 Charles Street has been one of the most exclusive addresses in Mayfair since 1966. You cannot enter without membership. Walk Charles Street in the early evening and observe the cars outside, the discreet entrance, the impeccable Georgian facade, and the quality of coats disappearing through the door. The exterior is the LARP. The interior requires an invitation that cannot be engineered.',
51.5083, -0.1446,
NULL,
5,
'{"men": {"brands": ["Huntsman", "Brioni", "Patek Philippe", "Foster & Son"], "outfit": {"top": "A Savile Row suit — this is not a blazer situation. Mark''s Club is the definitive London private dining club and the dress code is implicit and absolute.", "bottom": "Matching suit trousers", "shoes": "Black or dark tan hand-lasted Oxfords", "bag": "Nothing", "accessories": "Patek Philippe, silk tie, pocket square, a signet ring if inherited"}, "color_palette": "Charcoal, midnight navy, white — the private Mayfair dining club dress code has not changed in fifty years because it was correct from the beginning", "budget_dupe": "Walk Charles Street. Observe. Look like someone returning to collect a forgotten umbrella. The LARP is entirely exterior."}, "women": {"brands": ["Chanel", "Valentino", "Cartier", "Manolo Blahnik"], "outfit": {"top": "An evening dress or a beautifully cut cocktail dress — Mark''s is not a casual dinner venue", "bottom": "(dress)", "shoes": "A proper heel, always", "bag": "An evening clutch", "accessories": "A significant piece — a good brooch, real stones, the kind of jewelry that has been cleaned recently"}, "color_palette": "Black, deep jewel tones, ivory — the private club palette that has never needed revision", "budget_dupe": "You are walking past. Wear a beautiful coat with excellent shoes. A Georgian street in Mayfair on a winter evening is a LARP in itself."}}',
true),

('11111111-0000-0000-0000-000000000002',
'Harry''s Bar',
'Mayfair',
'Continental',
'The London outpost of the Venetian institution on South Audley Street has been a Mayfair fixture since 1979. The food is rich, Italian, and unapologetic. The room is small, the tables are close, the clientele is old Mayfair money and the people who orbit it. The Bellini is the obvious order. The veal is the correct order. Both are acceptable simultaneously.',
51.5075, -0.1533,
NULL,
4,
'{"men": {"brands": ["Brioni", "Zegna", "Patek Philippe", "Berluti"], "outfit": {"top": "A dark suit or an excellent blazer — Harry''s Bar is formal Italian dining and the room requires it", "bottom": "Tailored trousers, pressed", "shoes": "Dark leather Oxfords or monk straps", "bag": "Nothing", "accessories": "Patek Philippe or Cartier Santos, a pocket square, no tie required but a collar that can support one"}, "color_palette": "Midnight navy, charcoal, cream — Italian-Venetian formality in a Mayfair room", "budget_dupe": "A well-cut dark suit from SuitSupply, leather shoes polished. Harry''s Bar is about the quality of your presence at the table, not the name of your tailor."}, "women": {"brands": ["Dolce & Gabbana", "Valentino", "Bvlgari", "Aquazzura"], "outfit": {"top": "A cocktail dress in black, deep red, or champagne — Harry''s Bar rewards a certain Italian glamour", "bottom": "(dress) or wide-leg silk trousers with a jewelled top", "shoes": "A proper heel", "bag": "A small structured clutch or minaudière", "accessories": "Statement earrings, a good bracelet — Harry''s is the right venue for your gold"}, "color_palette": "Deep red, black, champagne, gold — the palette of a Venetian institution that has been consistent since 1931", "budget_dupe": "A beautiful vintage cocktail dress. Harry''s Bar in London is the kind of room where a well-worn dress from the right decade reads as better than something new."}}',
true),

('11111111-0000-0000-0000-000000000002',
'Scott''s Mayfair',
'Mayfair',
'Power Lunch',
'The Mount Street restaurant has been feeding the right people since 1851 — originally as an oyster warehouse near Piccadilly, now as the most reliable power lunch and power dinner address in Mayfair. The oak-panelled room, the lobster tank, and the quality of the fish are constants. The pavement tables in summer are the best outdoor dining in Mayfair. The clientele on any given lunchtime includes several people you have heard of.',
51.5102, -0.1504,
NULL,
4,
'{"men": {"brands": ["Turnbull & Asser", "Ralph Lauren Purple Label", "Rolex", "Church''s"], "outfit": {"top": "A blazer or suit jacket — Scott''s lunch is a working occasion and the standard is business formality", "bottom": "Dark navy or charcoal trousers, pressed", "shoes": "Church''s or Crockett & Jones in tan or black, polished", "bag": "A slim briefcase or portfolio", "accessories": "Rolex Datejust or Submariner, a pocket square, possibly a tie"}, "color_palette": "Navy, charcoal, cream — Mayfair power lunch in a room that has been serving it since Victoria''s time", "budget_dupe": "A good dark blazer and pressed trousers from M&S Autograph. Church''s shoes from their own sale. Scott''s rewards looking like you belong rather than looking like you tried."}, "women": {"brands": ["Roland Mouret", "Victoria Beckham", "Cartier", "Gianvito Rossi"], "outfit": {"top": "A structured blazer or tailored dress in a confident colour — the Mount Street lunch crowd does not do neutral", "bottom": "Tailored trousers or a knee-length pencil skirt", "shoes": "A pointed-toe heel in a quality leather", "bag": "A structured tote or ladybag that closes properly", "accessories": "Cartier, a silk scarf, pearl earrings or gold — the Scott''s terrace in summer is photographed by people who notice these things"}, "color_palette": "Deep teal, burgundy, camel, navy — Mount Street power colours that have been winning arguments since 1851", "budget_dupe": "Reiss or Hobbs for the tailored dress or blazer. The Mount Street clientele have opinions but they are principally about the lobster."}}',
true),

('11111111-0000-0000-0000-000000000002',
'Sexy Fish',
'Mayfair',
'Continental',
'Richard Caring''s 2015 restaurant in Berkeley Square is the most visually committed dining room in London: a 25-foot aquarium wall, coral sculptures by Damien Hirst, bronze mermaids by Frank Gehry, and a Coral Room of staggering excess. The Japanese-influenced menu is genuinely good. The cocktail programme is excellent. It is the correct level of maximalism — never kitsch because the budget was too large for kitsch.',
51.5112, -0.1481,
NULL,
4,
'{"men": {"brands": ["Tom Ford", "Saint Laurent", "Audemars Piguet", "Berluti"], "outfit": {"top": "A dark slim blazer or a dressed-up casual jacket — Sexy Fish is fashion-forward without requiring a suit", "bottom": "Dark slim trousers or premium black jeans", "shoes": "A quality leather shoe or fashion-adjacent boot in black", "bag": "Nothing", "accessories": "AP Royal Oak or a design-forward watch, a single ring — the Damien Hirst corals in the room will compete with anything too elaborate"}, "color_palette": "Black, dark navy, with one deliberate flash of colour — the room provides the spectacle, your job is to provide a coherent counterpoint", "budget_dupe": "A fitted black blazer from anywhere, black jeans, good shoes. Sexy Fish''s room is strong enough that it elevates every outfit in it."}, "women": {"brands": ["Saint Laurent", "Versace", "Messika", "Louboutin"], "outfit": {"top": "A dress that justifies the room — something silk, something strong, something that understands this is a spectacle and participates accordingly", "bottom": "(dress) or a fashion-forward separates combination", "shoes": "A heel with conviction — the floor is marble and the room notices", "bag": "A small structured bag or a clutch that matches the occasion", "accessories": "Statement earrings or a body chain — Sexy Fish is the right venue for the piece you bought at the gallery opening"}, "color_palette": "Black, deep coral, emerald, gold — the aquarium wall and the coral sculptures are the décor, and they are not subtle", "budget_dupe": "One great vintage piece in a strong colour or texture. Sexy Fish''s lighting is flattering and the room so overwhelming that a single confident choice reads as a complete outfit."}}',
true),

('11111111-0000-0000-0000-000000000002',
'Sketch',
'Mayfair',
'Art World',
'Pierre Gagnaire and Mourad Mazouz''s 2002 Conduit Street institution contains several distinct rooms at different registers: the Gallery (pink velvet, David Shrigley drawings), the Glade (enchanted forest), the Lecture Room (two Michelin stars), and the egg-pod loos that every visitor photographs. It is simultaneously an art installation, a Michelin-starred restaurant, and a place to have afternoon tea in pink velvet. Come for the room as much as the food.',
51.5121, -0.1427,
NULL,
3,
'{"men": {"brands": ["Acne Studios", "Dries Van Noten", "Nomos", "Common Projects"], "outfit": {"top": "Something considered and slightly unexpected — the Gallery''s pink velvet rewards deliberate dressing rather than conventional dressing", "bottom": "Dark tailored trousers or premium dark jeans", "shoes": "Clean minimal shoes or an interesting boot", "bag": "Nothing or a minimal tote", "accessories": "A design-forward watch, possibly a considered ring"}, "color_palette": "Black, deep grey, with one intentional colour note — the room is pink and opinionated and will not compete with your pattern", "budget_dupe": "COS or Arket for the architectural basics, one interesting vintage piece. Sketch rewards an eye rather than a budget."}, "women": {"brands": ["Simone Rocha", "Molly Goddard", "Charlotte Tilbury (the makeup)", "Miu Miu"], "outfit": {"top": "Something that responds to the pink room — a contrasting strong colour or an equally opulent texture", "bottom": "(dress) or a skirt with volume", "shoes": "An interesting shoe — the egg-pod loos are photographed alongside your feet", "bag": "An architectural or whimsical bag — Sketch is the venue where your Loewe Puzzle or JW Anderson Moon bag makes sense", "accessories": "A deliberate statement piece — Sketch is the venue where accessories function as art"}, "color_palette": "A colour that confronts the pink room — cobalt, citron, deep forest green, or lean fully into the pink and go monochromatic", "budget_dupe": "A vintage piece in a strong colour from a charity shop or Depop. Sketch''s Gallery rewards imagination and the egg-pod loos photograph any outfit dramatically well."}}',
true),

('11111111-0000-0000-0000-000000000002',
'Bob Bob Ricard',
'Soho',
'Continental',
